import React, { useState } from 'react';
import { useOSStore } from '../store/useOSStore';
import {
  Phone,
  MessageSquare,
  Camera,
  AlertOctagon,
  Clock,
  Volume2,
  Pin,
  ChevronLeft,
  Users,
  Plus
} from 'lucide-react';

export default function PhoneWidget() {
  const [activeScreen, setActiveScreen] = useState('home'); // 'home' | 'calls' | 'sms' | 'camera' | 'emergency' | 'vectors' | 'evidence'

  // Social Vectors Data (Trust, Rivalry, Sync, Corruption)
  const [socialNPCs] = useState([
    { id: 'voss', name: 'Dr. Maelis Voss', role: 'Veil Studies Head', trust: 80, rivalry: 10, sync: 90, corruption: 15, location: 'Lab 4' },
    { id: 'riven', name: 'Riven', role: 'Cyacademy Senior', trust: 65, rivalry: 45, sync: 70, corruption: 5, location: 'Courtyard' },
    { id: 'sissi', name: 'Sissi', role: 'House Rep', trust: 40, rivalry: 80, sync: 35, corruption: 20, location: 'Dorm B' },
    { id: 'odd', name: 'Odd', role: 'Netrunner Tech', trust: 95, rivalry: 5, sync: 85, corruption: 0, location: 'Workshop' },
    { id: 'mara', name: 'Agent Mara Quell', role: 'DGA Agent', trust: 75, rivalry: 30, sync: 60, corruption: 25, location: 'DGA HQ' },
  ]);
  const [selectedNPC, setSelectedNPC] = useState(socialNPCs[0]);

  // Calls & Voicemails Data
  const [voicemails] = useState([
    { id: 1, sender: 'Dean Cassian Rook', duration: '0:42', time: '08:30 AM', text: 'Player, orientation requires your verified Aura Passport stamp.' },
    { id: 2, sender: 'Unknown Number', duration: '0:18', time: '09:05 AM', text: '[ENCRYPTED VOICEMAIL]: Old Factory Ward lower floor has active data bleed.' },
  ]);
  const [activeCallLog, setActiveCallLog] = useState('');

  // SMS Texting Data
  const [smsThreads, setSmsThreads] = useState({
    'Odd': [
      { id: 1, sender: 'Odd', text: 'Hey! Got the laser arrow rig reloaded for the evening drill.', time: '09:10' },
      { id: 2, sender: 'Odd', text: 'Meet at the workshop if you need your deck tuned up!', time: '09:12' },
    ],
    'Riven': [
      { id: 3, sender: 'Riven', text: 'Don’t forget the Syntax HW due at 22:00. Rook is watching.', time: '08:50' },
    ],
    'Sissi': [
      { id: 4, sender: 'Sissi', text: 'House Vector is holding the evening briefing. Don’t be late.', time: '09:02' },
    ],
  });
  const [activeSmsContact, setActiveSmsContact] = useState('Odd');
  const [smsInput, setSmsInput] = useState('');

  // Evidence Board Data
  const [evidenceItems, setEvidenceItems] = useState([
    { id: 1, title: 'Sector 7 Data Bleed', type: 'photo', tag: 'DGA Breach', note: 'Unregistered frequency recorded near dead drop.' },
    { id: 2, title: 'Purge Genealogy Fragment', type: 'document', tag: 'Archivist Record', note: 'Lineage key matches Seraphima mark.' },
    { id: 3, title: 'Faith Intake Log', type: 'medical', tag: 'Aura Health', note: 'Veilwilt condition detected during intake.' },
  ]);
  const [newNoteTitle, setNewNoteTitle] = useState('');

  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);

  const handleSendSms = (e) => {
    if (e.key !== 'Enter' || !smsInput.trim()) return;
    setSmsThreads((prev) => ({
      ...prev,
      [activeSmsContact]: [
        ...(prev[activeSmsContact] || []),
        { id: Date.now(), sender: 'You', text: smsInput.trim(), time: 'Just now' },
      ],
    }));
    setSmsInput('');
  };

  const handleTriggerEmergency = (unit) => {
    setActiveCallLog(`🚨 EMERGENCY CALL DISPATCHED TO: ${unit.toUpperCase()}... UNIT RESPONDING.`);
  };

  const handleCaptureEvidence = () => {
    const newId = Date.now();
    setEvidenceItems((prev) => [
      ...prev,
      { id: newId, title: `Snapshot #${prev.length + 1}`, type: 'photo', tag: 'Aura Scan', note: 'Captured via Camera Lens' }
    ]);
    addCredits(50);
    addXP(25);
    alert('📷 Evidence snapshot captured & pinned to Evidence Board! (+50 ₡, +25 XP)');
  };

  const handleAddEvidenceNote = () => {
    if (!newNoteTitle.trim()) return;
    setEvidenceItems((prev) => [
      ...prev,
      { id: Date.now(), title: newNoteTitle.trim(), type: 'note', tag: 'Investigation', note: 'Manual evidence note pinned.' }
    ]);
    setNewNoteTitle('');
  };

  return (
    <div className="w-[280px] h-[520px] rounded-[36px] border-[8px] border-slate-900 bg-slate-950 shadow-2xl flex flex-col justify-between p-3 select-none text-white relative font-sans">
      {/* ------------------------------------------------------------------ */}
      {/* TOP STATUS BAR & SPEAKER NOTCH                                      */}
      {/* ------------------------------------------------------------------ */}
      <div className="flex justify-between items-center text-[10px] font-mono font-bold text-white px-2 py-0.5 border-b border-white/10 shrink-0">
        <span>09:41</span>
        <div className="h-2 w-14 bg-slate-800 rounded-full" />
        <div className="flex gap-1.5 items-center">
          <span>📶 5G</span>
          <span>🔋 100%</span>
        </div>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* PHONE SCREEN CONTENT AREA                                          */}
      {/* ------------------------------------------------------------------ */}
      <div className="flex-1 my-2 flex flex-col justify-between overflow-hidden relative">
        {/* HOME SCREEN (LOCK-CLOCK WIDGET & APP TILES GRID) */}
        {activeScreen === 'home' && (
          <div className="h-full flex flex-col justify-between space-y-3 p-1">
            {/* Quick-Glance Lock-Clock Widget */}
            <div className="rounded-2xl border border-white/15 bg-white/10 backdrop-blur-md p-3 text-center space-y-1 shadow-sm">
              <div className="text-3xl font-bold font-mono tracking-wider text-cyan-300">09:41</div>
              <div className="text-[10px] font-semibold text-amber-300 flex items-center justify-center gap-1">
                <Clock size={12} /> Evening (Cycle 28.07)
              </div>
              <div className="text-[9px] text-white/70 pt-1 border-t border-white/10 flex justify-between">
                <span>DGA Patrol: <strong className="text-red-400">Sector 7</strong></span>
                <span>Aura: <strong className="text-emerald-400">100%</strong></span>
              </div>
            </div>

            {/* Flat App Icon Tiles Grid */}
            <div className="grid grid-cols-3 gap-2.5 my-auto">
              {/* Phone / Voicemail */}
              <button
                onClick={() => setActiveScreen('calls')}
                className="flex flex-col items-center group"
              >
                <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-emerald-400 to-teal-600 shadow-md flex items-center justify-center text-white group-hover:scale-105 transition">
                  <Phone size={22} />
                </div>
                <span className="text-[9px] font-medium text-white/90 mt-1">Phone</span>
              </button>

              {/* SMS Messages */}
              <button
                onClick={() => setActiveScreen('sms')}
                className="flex flex-col items-center group"
              >
                <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-pink-400 to-purple-600 shadow-md flex items-center justify-center text-white group-hover:scale-105 transition">
                  <MessageSquare size={22} />
                </div>
                <span className="text-[9px] font-medium text-white/90 mt-1">Messages</span>
              </button>

              {/* Camera Lens */}
              <button
                onClick={() => setActiveScreen('camera')}
                className="flex flex-col items-center group"
              >
                <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-slate-400 to-slate-700 shadow-md flex items-center justify-center text-white group-hover:scale-105 transition">
                  <Camera size={22} />
                </div>
                <span className="text-[9px] font-medium text-white/90 mt-1">Camera</span>
              </button>

              {/* Social Vectors */}
              <button
                onClick={() => setActiveScreen('vectors')}
                className="flex flex-col items-center group"
              >
                <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-cyan-400 to-blue-600 shadow-md flex items-center justify-center text-white group-hover:scale-105 transition">
                  <Users size={22} />
                </div>
                <span className="text-[9px] font-medium text-white/90 mt-1">Vectors</span>
              </button>

              {/* Evidence Board */}
              <button
                onClick={() => setActiveScreen('evidence')}
                className="flex flex-col items-center group"
              >
                <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-amber-400 to-orange-600 shadow-md flex items-center justify-center text-white group-hover:scale-105 transition">
                  <Pin size={22} />
                </div>
                <span className="text-[9px] font-medium text-white/90 mt-1">Evidence</span>
              </button>

              {/* Emergency Dial */}
              <button
                onClick={() => setActiveScreen('emergency')}
                className="flex flex-col items-center group"
              >
                <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-red-500 to-red-700 shadow-md flex items-center justify-center text-white group-hover:scale-105 transition animate-pulse">
                  <AlertOctagon size={22} />
                </div>
                <span className="text-[9px] font-bold text-red-400 mt-1">Emergency</span>
              </button>
            </div>
          </div>
        )}

        {/* FULL-SCREEN PHONE APP VIEWS WITH TOP HEADER & BACK BUTTON */}
        {activeScreen !== 'home' && (
          <div className="h-full flex flex-col justify-between bg-slate-900/90 rounded-2xl p-2.5 border border-white/10 text-xs">
            {/* App Header Bar */}
            <div className="flex items-center justify-between border-b border-white/10 pb-1.5 mb-1 shrink-0 font-mono">
              <button
                onClick={() => setActiveScreen('home')}
                className="flex items-center gap-1 text-[10px] font-bold text-cyan-300 hover:text-white transition"
              >
                <ChevronLeft size={14} /> Back
              </button>
              <span className="font-bold text-[10px] uppercase tracking-wide text-white">
                {activeScreen}
              </span>
              <div className="w-4" />
            </div>

            {/* CALLS & VOICEMAIL APP SCREEN */}
            {activeScreen === 'calls' && (
              <div className="flex-1 flex flex-col justify-between overflow-hidden font-mono">
                {activeCallLog && (
                  <div className="rounded-lg bg-red-950/80 border border-red-500/40 p-2 text-red-300 text-[9px] animate-pulse my-1">
                    {activeCallLog}
                  </div>
                )}

                <div className="flex-1 overflow-auto space-y-2 pr-1">
                  <div className="text-[10px] font-bold text-amber-300">📼 Voicemail Archive:</div>
                  {voicemails.map((vm) => (
                    <div key={vm.id} className="rounded-lg border border-white/10 bg-slate-950/80 p-2 space-y-1">
                      <div className="flex justify-between text-[9px]">
                        <span className="font-bold text-cyan-300">{vm.sender}</span>
                        <span className="text-white/40">{vm.time}</span>
                      </div>
                      <div className="text-[9px] text-white/80 leading-snug">{vm.text}</div>
                      <button
                        onClick={() => alert(`▶ Playing voicemail from ${vm.sender}...`)}
                        className="flex items-center gap-1 text-[9px] font-bold text-emerald-400 hover:text-emerald-300"
                      >
                        <Volume2 size={11} /> Play Audio ({vm.duration})
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* SMS MESSAGES APP SCREEN */}
            {activeScreen === 'sms' && (
              <div className="flex-1 flex flex-col justify-between overflow-hidden font-mono">
                <div className="flex gap-1 overflow-x-auto py-1 border-b border-white/10 text-[9px]">
                  {Object.keys(smsThreads).map((contact) => (
                    <button
                      key={contact}
                      onClick={() => setActiveSmsContact(contact)}
                      className={`px-2 py-0.5 rounded-full transition ${
                        activeSmsContact === contact ? 'bg-pink-500 text-slate-950 font-bold' : 'bg-white/10 text-white/60'
                      }`}
                    >
                      {contact}
                    </button>
                  ))}
                </div>

                <div className="flex-1 overflow-auto space-y-1.5 my-1.5 pr-1">
                  {(smsThreads[activeSmsContact] || []).map((msg) => (
                    <div
                      key={msg.id}
                      className={`rounded-lg p-2 border space-y-0.5 ${
                        msg.sender === 'You' ? 'bg-purple-950/60 border-purple-400/40 ml-3' : 'bg-slate-950/70 border-white/10 mr-3'
                      }`}
                    >
                      <div className="flex justify-between text-[9px]">
                        <span className="font-bold text-cyan-300">{msg.sender}</span>
                        <span className="text-white/40">{msg.time}</span>
                      </div>
                      <div className="text-[9px] text-white/90">{msg.text}</div>
                    </div>
                  ))}
                </div>

                <input
                  type="text"
                  value={smsInput}
                  onChange={(e) => setSmsInput(e.target.value)}
                  onKeyDown={handleSendSms}
                  placeholder={`Text ${activeSmsContact}...`}
                  className="w-full rounded-lg border border-pink-400/40 bg-black/60 px-2 py-1.5 text-[10px] text-white outline-none focus:border-pink-400 font-mono"
                />
              </div>
            )}

            {/* CAMERA LENS APP SCREEN */}
            {activeScreen === 'camera' && (
              <div className="flex-1 flex flex-col justify-between text-center font-mono">
                <div className="relative w-full h-36 rounded-xl border border-dashed border-cyan-400/60 bg-black/60 overflow-hidden flex items-center justify-center my-auto">
                  <div className="absolute inset-2 border border-cyan-400/30 rounded-lg pointer-events-none" />
                  <span className="text-[10px] text-cyan-300 animate-pulse">LENS: EVIDENCE SCANNER ACTIVE</span>
                </div>

                <button
                  onClick={handleCaptureEvidence}
                  className="w-full rounded-xl border border-cyan-400 bg-cyan-500/20 py-2 font-bold text-cyan-300 hover:bg-cyan-500/40 transition text-xs flex items-center justify-center gap-1.5"
                >
                  <Camera size={14} /> [ CAPTURE EVIDENCE ]
                </button>
              </div>
            )}

            {/* EMERGENCY DIAL APP SCREEN */}
            {activeScreen === 'emergency' && (
              <div className="flex-1 flex flex-col justify-between font-mono">
                <div className="space-y-2 my-auto">
                  <button
                    onClick={() => handleTriggerEmergency('Faith Medical Group')}
                    className="w-full rounded-xl border border-red-400 bg-red-600/30 p-2.5 text-left hover:bg-red-600/50 transition"
                  >
                    <div className="font-bold text-white text-[11px]">🏥 Faith Medical Group</div>
                    <div className="text-[9px] text-red-200">Dispatches aura stabilization squad.</div>
                  </button>

                  <button
                    onClick={() => handleTriggerEmergency('DGA Response Unit')}
                    className="w-full rounded-xl border border-red-400 bg-red-600/30 p-2.5 text-left hover:bg-red-600/50 transition"
                  >
                    <div className="font-bold text-white text-[11px]">🛡️ DGA Response Unit</div>
                    <div className="text-[9px] text-red-200">Triggers tactical perimeter lockdown.</div>
                  </button>

                  <button
                    onClick={() => handleTriggerEmergency('Campus Security')}
                    className="w-full rounded-xl border border-red-400 bg-red-600/30 p-2.5 text-left hover:bg-red-600/50 transition"
                  >
                    <div className="font-bold text-white text-[11px]">🚨 Cyacademy Security</div>
                    <div className="text-[9px] text-red-200">Alerts Dean Rook & campus guards.</div>
                  </button>
                </div>
              </div>
            )}

            {/* SOCIAL VECTORS APP SCREEN */}
            {activeScreen === 'vectors' && (
              <div className="flex-1 flex flex-col justify-between font-mono text-[10px]">
                <div className="flex gap-1 overflow-x-auto pb-1 border-b border-white/10">
                  {socialNPCs.map((npc) => (
                    <button
                      key={npc.id}
                      onClick={() => setSelectedNPC(npc)}
                      className={`px-1.5 py-0.5 rounded text-[8px] whitespace-nowrap transition ${
                        selectedNPC.id === npc.id ? 'bg-cyan-500 text-slate-950 font-bold' : 'bg-white/10 text-white/60'
                      }`}
                    >
                      {npc.name}
                    </button>
                  ))}
                </div>

                <div className="rounded-xl border border-cyan-400/30 bg-slate-950/80 p-2.5 space-y-1.5 my-auto">
                  <div className="font-bold text-cyan-300 border-b border-white/10 pb-0.5">
                    {selectedNPC.name} ({selectedNPC.role})
                  </div>

                  <div className="space-y-1 text-[9px]">
                    <div>
                      <div className="flex justify-between text-[8px]">
                        <span className="text-emerald-400">Trust Vector:</span>
                        <span>{selectedNPC.trust}%</span>
                      </div>
                      <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
                        <div className="bg-emerald-400 h-full" style={{ width: `${selectedNPC.trust}%` }} />
                      </div>
                    </div>

                    <div>
                      <div className="flex justify-between text-[8px]">
                        <span className="text-amber-400">Rivalry Vector:</span>
                        <span>{selectedNPC.rivalry}%</span>
                      </div>
                      <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
                        <div className="bg-amber-400 h-full" style={{ width: `${selectedNPC.rivalry}%` }} />
                      </div>
                    </div>

                    <div>
                      <div className="flex justify-between text-[8px]">
                        <span className="text-cyan-400">Sync Vector:</span>
                        <span>{selectedNPC.sync}%</span>
                      </div>
                      <div className="w-full bg-slate-800 h-1 rounded-full overflow-hidden">
                        <div className="bg-cyan-400 h-full" style={{ width: `${selectedNPC.sync}%` }} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* EVIDENCE BOARD APP SCREEN */}
            {activeScreen === 'evidence' && (
              <div className="flex-1 flex flex-col justify-between font-mono text-[10px]">
                <div className="flex-1 overflow-auto space-y-1.5 my-1 pr-1">
                  {evidenceItems.map((item) => (
                    <div key={item.id} className="rounded-lg border border-amber-400/30 bg-slate-950/80 p-2 space-y-0.5">
                      <div className="flex justify-between items-center font-bold text-amber-300">
                        <span>📌 {item.title}</span>
                        <span className="text-[8px] bg-amber-400/20 px-1 py-0.5 rounded text-amber-200">{item.tag}</span>
                      </div>
                      <div className="text-[9px] text-white/80">{item.note}</div>
                    </div>
                  ))}
                </div>

                <div className="flex gap-1 pt-1 border-t border-white/10">
                  <input
                    type="text"
                    value={newNoteTitle}
                    onChange={(e) => setNewNoteTitle(e.target.value)}
                    placeholder="Add evidence note..."
                    className="flex-1 rounded border border-amber-400/40 bg-black/60 px-2 py-1 text-[9px] text-white outline-none"
                  />
                  <button
                    onClick={handleAddEvidenceNote}
                    className="px-2 py-1 bg-amber-500 text-slate-950 font-bold rounded hover:bg-amber-400 transition text-[9px]"
                  >
                    <Plus size={12} />
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* BOTTOM HOME INDICATOR BAR                                           */}
      {/* ------------------------------------------------------------------ */}
      <div className="flex justify-center pb-0.5 shrink-0">
        <button
          onClick={() => setActiveScreen('home')}
          className="h-1.5 w-20 bg-white/70 rounded-full hover:bg-white transition cursor-pointer"
          title="Return to Home Screen"
        />
      </div>
    </div>
  );
}
